import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {createHash} from 'node:crypto';
import {gzipSync,gunzipSync} from 'node:zlib';
import {footprintHash} from './check-prepared.mjs';
import {normalizePreparedEvidence,preparedEvidenceJSON,validatePreparedEvidenceIndex} from '../src/prepared-evidence.js';
const sha=raw=>createHash('sha256').update(raw).digest('hex');
const read=file=>JSON.parse(file.endsWith('.gz')?gunzipSync(fs.readFileSync(file)):fs.readFileSync(file));
const defaults=[{id:'dated-reference-names',kind:'names'},{id:'demographic-evidence',kind:'records'},{id:'population-ghsl',kind:'records'}];
export function prepareEvidenceBundle({data='data',output=`${data}/prepared-evidence`,products=defaults}={}){
 const hierarchy=read(`${data}/hierarchy.json`),features=read(`${data}/world-index.json`).parts.flatMap(p=>read(`${data}/${p}`).features),proof={footprints_sha256:footprintHash(features),hierarchy_sha256:sha(fs.readFileSync(`${data}/hierarchy.json`))};
 const entityIds=new Set([...hierarchy.map(u=>u.id),...features.map(f=>f.id)]),locationIds=new Set(features.map(f=>f.id)),sources=new Map(),categories=new Map(),groups=new Map(),rowsByKind={records:new Map(),names:new Map()},productProofs=[],pending=[];
 for(const product of products){
  if(!['names','records'].includes(product.kind))throw Error('Unsupported prepared product kind');
  const directory=product.directory??`${data}/${product.id}`,manifestFile=`${directory}/index.json`;
  if(!fs.existsSync(manifestFile)){pending.push({id:product.id,reason:'Producer manifest is not ready'});continue;}
  const manifest=read(manifestFile),producerProofFile=`${directory}/proof.json`,producerProof=fs.existsSync(producerProofFile)?read(producerProofFile):{},sourceRows=manifest.sources??(fs.existsSync(`${directory}/sources.json`)?read(`${directory}/sources.json`):null);
  if(!Array.isArray(sourceRows)){pending.push({id:product.id,reason:'Full provenance source rows are not ready'});continue;}
  if(producerProof.footprints_sha256&&producerProof.footprints_sha256!==proof.footprints_sha256||producerProof.hierarchy_sha256&&producerProof.hierarchy_sha256!==proof.hierarchy_sha256)throw Error(`Stale producer proof: ${product.id}`);
  if(manifest.footprints_sha256&&manifest.footprints_sha256!==proof.footprints_sha256||manifest.hierarchy_sha256&&manifest.hierarchy_sha256!==proof.hierarchy_sha256)throw Error(`Stale producer geography: ${product.id}`);
  if(manifest.location_index_sha256&&manifest.location_index_sha256!==sha(fs.readFileSync(`${data}/world-index.json`)))throw Error(`Stale producer location index: ${product.id}`);
  const inputs=[{path:'index.json',sha256:sha(fs.readFileSync(manifestFile))}],localSources=new Map();if(fs.existsSync(producerProofFile))inputs.push({path:'proof.json',sha256:sha(fs.readFileSync(producerProofFile))});
  for(const source of sourceRows){if(!source.id||!source.name||!source.license||!source.vintage||!['historical','reference','estimate','example'].includes(source.status))throw Error(`Incomplete prepared source ${product.id}`);const old=sources.get(source.id);if(old&&preparedEvidenceJSON(old)!==preparedEvidenceJSON(source))throw Error(`Source identity collision: ${source.id}`);sources.set(source.id,source);localSources.set(source.id,source);}
  if(fs.existsSync(`${directory}/sources.json`)){const digest=sha(fs.readFileSync(`${directory}/sources.json`));if(manifest.sources_sha256&&manifest.sources_sha256!==digest)throw Error('Producer sources hash mismatch');inputs.push({path:'sources.json',sha256:digest});}
  const categoryFile=`${directory}/categories.json`;if(fs.existsSync(categoryFile)){const digest=sha(fs.readFileSync(categoryFile));if(manifest.categories_sha256&&manifest.categories_sha256!==digest)throw Error('Producer categories hash mismatch');inputs.push({path:'categories.json',sha256:digest});for(const category of read(categoryFile)){const old=categories.get(category.id);if(old&&preparedEvidenceJSON(old)!==preparedEvidenceJSON(category))throw Error('Category identity collision');if(!category.source_id)throw Error(`Category requires source provenance: ${category.id}`);categories.set(category.id,category);}}
  const parts=manifest.record_parts??manifest.parts??(fs.existsSync(`${directory}/religion-records.json`)?['religion-records.json']:[]);if(!parts.length)throw Error(`Producer contains no evidence assets: ${product.id}`);
  let count=0;
  for(const part of parts){const name=typeof part==='string'?part:part.path;if(!name||path.isAbsolute(name)||name.split('/').includes('..'))throw Error('Unsafe producer part path');const file=`${directory}/${name}`,raw=fs.readFileSync(file),digest=sha(raw);if(part.sha256&&part.sha256!==digest)throw Error('Producer evidence hash mismatch');const pinned=producerProof.parts?.find(p=>p.path===name);if(pinned&&(pinned.sha256!==digest||pinned.bytes!==raw.length))throw Error('Producer proof evidence hash/size mismatch');inputs.push({path:name,sha256:digest});const records=read(file);if(!Array.isArray(records))throw Error('Producer evidence must be rows');if(part.records!=null&&part.records!==records.length)throw Error('Producer part count mismatch');for(const row of records){normalizePreparedEvidence(row,product.kind,localSources);if(!(product.kind==='names'?entityIds:locationIds).has(product.kind==='names'?row.entity_id:row.location_id))throw Error(`Evidence identity outside current geography: ${row.id}`);if(rowsByKind[product.kind].has(row.id))throw Error(`Duplicate prepared identity: ${row.id}`);rowsByKind[product.kind].set(row.id,row);const key=`${product.kind}:${row.valid_from}:${row.valid_to}`;if(!groups.has(key))groups.set(key,{kind:product.kind,valid_from:row.valid_from,valid_to:row.valid_to,rows:[]});groups.get(key).rows.push(row);count++;}}
  if(manifest.records!=null&&manifest.records!==count)throw Error(`Producer record count mismatch: ${product.id}`);
  for(const name of ['source-receipts.json','location-crosswalk.json','crosswalk.json.gz'])if(fs.existsSync(`${directory}/${name}`))inputs.push({path:name,sha256:sha(fs.readFileSync(`${directory}/${name}`))});
  productProofs.push({id:product.id,directory:path.relative(data,directory),manifest_sha256:inputs[0].sha256,inputs,records:product.kind==='records'?count:0,names:product.kind==='names'?count:0,source_ids:sourceRows.map(s=>s.id),producer_proofs:{footprints_sha256:manifest.footprints_sha256??producerProof.footprints_sha256??null,hierarchy_sha256:manifest.hierarchy_sha256??null,location_index_sha256:manifest.location_index_sha256??null}});
 }
 for(const category of categories.values())if(!sources.has(category.source_id)||!['owner','culture','religion'].includes(category.kind)||!category.id||!category.name)throw Error('Invalid prepared category provenance');
 for(const r of rowsByKind.records.values())if(r.category_id&&(!categories.has(r.category_id)||categories.get(r.category_id).kind!==r.attribute))throw Error(`Unregistered or mismatched prepared category: ${r.category_id}`);
 const staging=`${output}.staging-${process.pid}`;fs.rmSync(staging,{recursive:true,force:true});fs.mkdirSync(`${staging}/imports`,{recursive:true});const index={version:1,...proof,sources:[...sources.values()],categories:[...categories.values()],products:productProofs,pending_products:pending,parts:[],records:rowsByKind.records.size,names:rowsByKind.names.size},imports={version:1,...proof,batches:[],counts:{sources:sources.size,categories:categories.size,records:index.records,names:index.names}};
 let number=0;
 for(const group of [...groups.values()].sort((a,b)=>a.valid_from-b.valid_from||a.kind.localeCompare(b.kind)))for(let at=0;at<group.rows.length;at+=1000){const rows=group.rows.slice(at,at+1000),decoded=preparedEvidenceJSON(rows),raw=gzipSync(decoded),name=`part-${number++}.json.gz`;fs.writeFileSync(`${staging}/${name}`,raw);index.parts.push({path:name,kind:group.kind,valid_from:group.valid_from,valid_to:group.valid_to,records:rows.length,sha256:sha(raw),decoded_sha256:sha(decoded),bytes:raw.length,source_ids:[...new Set(rows.map(r=>r.source_id))]});}
 function emit(kind,rows){let part=[];function flush(){if(!part.length)return;const digest=sha(preparedEvidenceJSON(part)),payload={[kind]:part,ingestion_id:`prepared-evidence:${kind}:${digest}`},raw=preparedEvidenceJSON(payload),name=`batch-${imports.batches.length}.json`;fs.writeFileSync(`${staging}/imports/${name}`,raw);imports.batches.push({path:name,route:'/api/records/import',kind,rows:part.length,sha256:sha(raw)});part=[];}for(const row of rows){if(Buffer.byteLength(preparedEvidenceJSON(row))>16384&&['sources','categories'].includes(kind))throw Error('Prepared metadata exceeds source import budget');if(part.length===200||Buffer.byteLength(preparedEvidenceJSON({[kind]:[...part,row],ingestion_id:'prepared-evidence:'+kind+':'+('0'.repeat(64))}))>1048576)flush();part.push(row);if(Buffer.byteLength(preparedEvidenceJSON({[kind]:part}))>1048000)throw Error('Prepared row exceeds bounded import size');}flush();}
 emit('sources',index.sources);emit('categories',index.categories);emit('names',[...rowsByKind.names.values()]);emit('records',[...rowsByKind.records.values()]);
 validatePreparedEvidenceIndex(index);
 fs.writeFileSync(`${staging}/imports/index.json`,JSON.stringify(imports,null,2));index.imports={path:'imports/index.json',sha256:sha(fs.readFileSync(`${staging}/imports/index.json`)),batches:imports.batches.length};fs.writeFileSync(`${staging}/index.json`,JSON.stringify(index,null,2));
 fs.mkdirSync(path.dirname(output),{recursive:true});const backup=`${output}.old-${process.pid}`;if(fs.existsSync(output))fs.renameSync(output,backup);try{fs.renameSync(staging,output);fs.rmSync(backup,{recursive:true,force:true});}catch(error){if(fs.existsSync(backup))fs.renameSync(backup,output);throw error;}return index;
}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){const index=prepareEvidenceBundle();console.log(JSON.stringify({records:index.records,names:index.names,parts:index.parts.length,pending_products:index.pending_products}));}
